// Generate a compelling cover art prompt based on the story
const plotData = $('Parse Plot JSON').first().json;
const narrativeResponse = $('Narrative Weaver').first().json;

// Handle different response structures from Gemini agents
let storyText;
if (narrativeResponse.output) {
  storyText = narrativeResponse.output;
} else if (narrativeResponse.text) {
  storyText = narrativeResponse.text;
} else if (narrativeResponse.content && narrativeResponse.content[0] && narrativeResponse.content[0].text) {
  storyText = narrativeResponse.content[0].text;
} else if (typeof narrativeResponse === 'string') {
  storyText = narrativeResponse;
} else {
  storyText = narrativeResponse.message || narrativeResponse.response || JSON.stringify(narrativeResponse);
}

// Extract key elements from the story for cover art
const title = plotData.title || 'Story Title';
const genre = plotData.genre || 'Adventure';
const moral = plotData.moral_lesson_summary || 'A story about friendship';
const setting = plotData.setting || 'An exciting adventure';
const logline = plotData.logline || 'An exciting story about two brothers';

// Create a compelling cover art prompt - NOW TRULY DYNAMIC!
const coverPrompt = `Professional children's book cover art, Pixar animation style, ultra-high quality digital illustration, vibrant colors, dramatic lighting. 

CHARACTER DESCRIPTIONS:
Angel is a light-skinned Latino, confident 12-year-old boy with black box braids who likes to wear basketball jerseys and hoodies of various colors. 
Jayson is a slightly lighter-skinned Latino, curious 10-year-old boy with cornrow braids who likes to wear baseball jerseys or sweatsuits.

STORY CONTEXT:
Title: "${title}"
Genre: ${genre}
Setting: ${setting}
Story Summary: ${logline}

The cover should visually capture the essence of this ${genre} story set in ${setting}. The mood and composition should reflect the theme: ${moral}

COVER SPECIFICATIONS: 
- Standard children's book cover dimensions (8.5" x 11" or 3:4 aspect ratio)
- The title "${title}" MUST be prominently displayed at the top in an elegant, readable font with subtle glow effect
- Author name "Shak & Jenn AI" must be printed at the bottom
- Professional book cover layout with proper margins and spacing
- High contrast, detailed, award-winning illustration quality
- 4K resolution, cinematic composition
- Perfect for printing and digital display
- Visually stunning and immediately captures attention
- Consistent with professional children's book publishing standards`;

return [{
  json: {
    coverPrompt: coverPrompt,
    storyTitle: title,
    storyText: storyText,
    plotData: plotData,
    genre: genre,
    setting: setting,
    moral: moral
  }
}];

// Check if image generation is complete and extract image URL
const response = $input.first().json;

console.log('Full response:', JSON.stringify(response, null, 2));
console.log('Response status:', response.status);
console.log('Has images array:', !!response.images);
console.log('Images length:', response.images?.length);

// Check if we already have images (completed response)
if (response.images && Array.isArray(response.images) && response.images.length > 0) {
  console.log('Image found, extracting URL:', response.images[0].url);
  return [{
    json: {
      imageUrl: response.images[0].url,
      requestId: response.request_id || 'unknown',
      status: 'COMPLETED',
      originalResponse: response
    }
  }];
}

// If still in queue, throw error to trigger retry
if (response.status === 'IN_QUEUE') {
  const queuePos = response.metrics?.queue_position || 'unknown';
  throw new Error(`Image still generating. Queue position: ${queuePos}. Retrying...`);
}

// If completed status but no images (fallback)
if (response.status === 'COMPLETED') {
  throw new Error('No images found in completed response');
}

// Handle failed status
if (response.status === 'FAILED') {
  throw new Error(`Image generation failed: ${response.error || 'Unknown error'}`);
}

// If no status but we have images, treat as completed
if (response.images && Array.isArray(response.images) && response.images.length > 0) {
  return [{
    json: {
      imageUrl: response.images[0].url,
      requestId: response.request_id || 'unknown',
      status: 'COMPLETED',
      originalResponse: response
    }
  }];
}

// Handle other cases
throw new Error(`Unexpected response format. Status: ${response.status || 'undefined'}, Has images: ${!!response.images}`);

// Aggregate downloaded images and quiz data (robust to missing branches)
const allInputs = $input.all();

function safeFirstJson(nodeName, fallback = null) {
  try {
    const node = $(nodeName);
    const first = node.first();
    return first && first.json ? first.json : fallback;
  } catch (e) {
    return fallback;
  }
}

const storyData = safeFirstJson('Parse Plot JSON', {});
const narrativeResponse = safeFirstJson('Narrative Weaver', {});
const quizDataRaw = safeFirstJson('Parse Quiz JSON', null);

// Handle different response structures from Gemini agents
let storyText;
if (narrativeResponse && narrativeResponse.output) {
  storyText = narrativeResponse.output;
} else if (narrativeResponse && narrativeResponse.text) {
  storyText = narrativeResponse.text;
} else if (narrativeResponse && narrativeResponse.content && narrativeResponse.content[0] && narrativeResponse.content[0].text) {
  storyText = narrativeResponse.content[0].text;
} else if (typeof narrativeResponse === 'string') {
  storyText = narrativeResponse;
} else {
  storyText = (narrativeResponse && (narrativeResponse.message || narrativeResponse.response)) || JSON.stringify(narrativeResponse || {});
}

// Separate cover art from scene images using imageType
let coverArtUrl = null;
const sceneImageUrls = [];

for (const input of allInputs) {
  const imageData = input.json || {};
  if (imageData.imageUrl) {
    if (imageData.imageType === 'cover') {
      coverArtUrl = imageData.imageUrl;
    } else {
      sceneImageUrls.push(imageData.imageUrl);
    }
  }
}

return [{
  json: {
    storyTitle: storyData?.title || 'Untitled Story',
    storyBody: storyText || '',
    coverArtUrl: coverArtUrl,
    imageUrls: JSON.stringify(sceneImageUrls),
    quiz: JSON.stringify(quizDataRaw ?? {}),
    plotData: JSON.stringify(storyData ?? {}),
    status: 'completed',
    processedAt: new Date().toISOString(),
    sceneCount: sceneImageUrls.length
  }
}];

// Parse the JSON response from Plot Architect (Gemini/LangChain format)
const response = $input.first().json;

// Handle different response structures from Gemini agents
let content;
if (response.output) {
  // LangChain agent response structure
  content = response.output;
} else if (response.text) {
  // Direct text response
  content = response.text;
} else if (response.content && response.content[0] && response.content[0].text) {
  // Anthropic-style response structure
  content = response.content[0].text;
} else if (typeof response === 'string') {
  // String response
  content = response;
} else {
  // Try to find text in the response
  content = response.message || response.response || JSON.stringify(response);
}

// Clean up the content (remove markdown formatting, extra whitespace)
content = content.trim().replace(/^```json\s*/, '').replace(/\s*```$/, '');

try {
  const parsedContent = JSON.parse(content);
  return {
    json: parsedContent
  };
} catch (error) {
  throw new Error('Failed to parse JSON from Plot Architect: ' + error.message + '\nContent: ' + content.substring(0, 200) + '...');
}

